refentry.refsect1:
&reftitle.parameters;


  callback



    Функция вызывается непосредственно перед отправкой заголовков, не содержит параметров, а значение возврата игнорируется.

  &reftitle.examples;

   Пример регистрации функции обратного вызова функцией header_register_callback


<?php

header('Content-Type: text/plain');
header('X-Test: foo');

function foo()
{
    foreach (headers_list() as $header) {
        if (strpos($header, 'X-Powered-By:') !== false) {
            header_remove('X-Powered-By');
        }
        header_remove('X-Test');
    }
}

$result = header_register_callback('foo');
echo "a";


   &example.outputs.similar;


Content-Type: text/plain

a

&reftitle.notes;


 Зарегистрированная функцией header_register_callback функция обратного вызова
 запускается прямо перед отправкой заголовков, поэтому в ряде сценариев вывод внутри callback-функции нарушает порядок вывода.

&note.network.header.sapi;
